function useSafeAuth() { const [u, setU] = useState<any>(null); useEffect(() => { let a = true; (async () => { try { const { data } = await sb.auth.getSession(); if (a) setU(data?.session?.user || null); } catch {} })(); let sub: any = null; try { const r = sb.auth.onAuthStateChange((_e: any, s: any) => { if (a) setU(s?.user || null); }); sub = r?.data; } catch {} return () => { a = false; try { sub?.subscription?.unsubscribe(); } catch {} }; }, []); return { user: u }; }
