function Comments({ video, onClose, onCount }: any) { const { user } = useSafeAuth(); const [text, setText] = useState(""); const [list, setList] = useState<any[]>([]); const [loading, setLoading] = useState(true); useEffect(() => { setLoading(true); const local = getLocal(`shorttok_comments_${video.id}`, []); setList(local); (async () => { try { const { data } = await sb.from("comments").select("*, profiles(username, avatar_url)").eq("video_id", video.id).order("created_at", { ascending: false }); if (data?.length) setList((p: any) => { const ids = new Set(p.map((x: any) => String(x.id))); return [...p, ...data.filter((x: any) => !ids.has(String(x.id)))]; }); } catch {} setLoading(false); })(); }, [video.id]); const send = async () => { if (!text.trim()) return; const nm = getLS("shorttok_username") || user?.email?.split("@")[0] || myName(); const nc = { id: "local-" + Date.now(), content: text.trim(), created_at: new Date().toISOString(), profiles: { username: nm } }; setList((p) => [nc, ...p]); setLocal(`shorttok_comments_${video.id}`, [nc, ...getLocal(`shorttok_comments_${video.id}`, [])]); setText(""); toast.success("কমেন্ট হয়ে গেছে ❤️"); pushNotify("💬 নতুন কমেন্ট", `${nm} কমেন্ট করেছে: ${nc.content.slice(0, 40)}`); if (onCount) onCount(1); if (user && !String(video.id).startsWith("demo-")) { try { await sb.from("comments").insert({ video_id: video.id, user_id: user.id, content: nc.content }); } catch {} } }; return (<div className="fixed inset-0 z-[100] flex items-end justify-center bg-black/70" onClick={onClose}><div className="w-full max-w-[420px] max-h-[70vh] bg-[#111] rounded-t-3xl p-4 flex flex-col text-white" onClick={(e) => e.stopPropagation()}><div className="flex justify-between"><b>💬 কমেন্ট ({list.length})</b><button onClick={onClose} className="text-2xl px-2">×</button></div><div className="flex-1 overflow-y-auto mt-3 space-y-3 min-h-[150px]">{loading && !list.length && <p className="text-white/50 text-center text-sm mt-6">লোড হচ্ছে…</p>}{!loading && !list.length && <p className="text-white/50 text-center text-sm mt-6">এখনো কোনো কমেন্ট নেই — তুমিই প্রথম করো 👇</p>}{list.map((c: any) => (<div key={c.id} className="flex gap-2"><div className="h-8 w-8 shrink-0 rounded-full bg-gradient-to-br from-orange-500 to-pink-600 flex items-center justify-center font-bold text-sm">{(c.profiles?.username || "S")[0].toUpperCase()}</div><div className="bg-zinc-900 rounded-2xl px-3 py-2 flex-1"><p className="text-[12px] font-bold">@{c.profiles?.username || "shorttok"}</p><p className="text-[13px]">{c.content}</p></div></div>))}</div><div className="flex gap-2 mt-3"><input value={text} onChange={(e) => setText(e.target.value)} onKeyDown={(e) => e.key === "Enter" && send()} placeholder="কমেন্ট লিখো... ❤️" className="flex-1 rounded-full bg-zinc-900 px-4 py-2.5 text-sm outline-none" /><button onClick={send} className="rounded-full bg-[#fe2c55] px-5 font-bold text-sm">পাঠাও</button></div></div></div>); }
function AddStatus({ onClose, onAdded }: any) { const [text, setText] = useState(""); const [preview, setPreview] = useState(""); const post = () => { if (!text.trim() && !preview) return toast.error("কিছু লিখো বা ছবি দাও"); const s = { id: "st-" + Date.now(), username: myName(), text: text.trim() || "📸 ছবি Status", image: preview, createdAt: Date.now(), likes: 0 }; setLocal("shorttok_status_list", [s, ...getLocal("shorttok_status_list", [])]); onAdded(s); toast.success("Status দেওয়া হয়ে গেছে ✅"); onClose(); }; return (<div className="fixed inset-0 z-[120] bg-black/80 flex items-end justify-center" onClick={onClose}><div className="w-full max-w-[420px] bg-white rounded-t-3xl p-4 text-black" onClick={(e) => e.stopPropagation()}><div className="flex justify-between"><b>✍️ Status দাও</b><button onClick={onClose} className="text-2xl px-2">×</button></div><div className="mt-3 rounded-2xl p-4 min-h-[120px] bg-gradient-to-br from-purple-500 to-pink-500 flex items-center justify-center">{preview ? <img src={preview} className="max-h-[160px] rounded-xl object-cover" alt="" /> : <textarea value={text} onChange={(e) => setText(e.target.value)} placeholder="তুমি কী ভাবছো? লিখো... ❤️" className="w-full bg-transparent text-white placeholder-white/80 text-center font-bold text-[16px] outline-none resize-none" rows={3} />}</div><label className="block mt-3 bg-zinc-100 rounded-2xl py-3 text-center text-sm font-bold cursor-pointer">🖼️ গ্যালারি থেকে ছবি দাও<input type="file" accept="image/*" className="hidden" onChange={(e) => { const f = e.target.files?.[0]; if (f) setPreview(URL.createObjectURL(f)); }} /></label><button onClick={post} className="w-full mt-3 bg-[#fe2c55] text-white rounded-full py-3 font-bold">Status দাও → সবাই দেখবে</button></div></div>); }
function StatusViewer({ statuses, index, onClose, onLike }: any) { const [idx, setIdx] = useState(index); const s = statuses[idx]; if (!s) return null; return (<div className="fixed inset-0 z-[130] bg-black text-white flex flex-col"><div className="flex gap-1 p-3">{statuses.map((_: any, i: number) => (<div key={i} className={`flex-1 h-1 rounded-full ${i === idx ? "bg-white" : "bg-white/30"}`} />))}</div><div className="flex items-center gap-2 px-4"><div className="h-9 w-9 rounded-full bg-gradient-to-br from-orange-500 to-pink-600 flex items-center justify-center font-bold">{s.username[0].toUpperCase()}</div><div><p className="font-bold text-sm">{s.username}</p><p className="text-[11px] text-white/60">{timeAgo(s.createdAt)}</p></div><button onClick={onClose} className="ml-auto bg-white/20 p-2 rounded-full"><X className="h-4 w-4" /></button></div><div className="flex-1 flex items-center justify-center p-4" onClick={() => { if (idx < statuses.length - 1) setIdx(idx + 1); else onClose(); }}>{s.image ? <img src={s.image} className="max-h-full rounded-2xl object-contain" alt="" /> : <div className="w-full max-w-[320px] aspect-square rounded-3xl bg-gradient-to-br from-purple-500 to-pink-500 flex items-center justify-center p-6 text-center text-[20px] font-bold">{s.text}</div>}</div><div className="p-4 flex gap-2"><button onClick={() => onLike(s.id)} className="flex-1 bg-zinc-900 rounded-full py-3 font-bold text-sm">❤️ লাইক ({s.likes || 0})</button><button onClick={() => { if (idx < statuses.length - 1) setIdx(idx + 1); else onClose(); }} className="flex-1 bg-[#fe2c55] rounded-full py-3 font-bold text-sm">পরের Status →</button></div></div>); }
function SoundPage({ sound, allVideos, onClose, onOpenVideo, onUseSound }: any) { const list = allVideos.filter((v: any) => v.sound === sound); return (<div className="fixed inset-0 z-[95] bg-black text-white overflow-y-auto"><button onClick={onClose} className="absolute top-4 right-4 z-10 rounded-full bg-white/20 p-2"><X /></button><div className="pt-10 px-4"><div className="flex items-center gap-3"><div className="h-16 w-16 rounded-2xl bg-gradient-to-br from-[#fe2c55] to-orange-500 flex items-center justify-center text-3xl">🎵</div><div><p className="font-bold text-[16px]">{sound}</p><p className="text-white/60 text-[12px]">{list.length} জন এই গান দিয়ে ভিডিও বানিয়েছে</p></div></div><button onClick={() => onUseSound(sound)} className="w-full mt-4 bg-[#fe2c55] rounded-full py-3 font-bold text-sm">🎵 এই গান দিয়ে ভিডিও বানাও</button></div><p className="px-4 mt-5 font-bold text-[14px]">🎬 এই গান দিয়ে বানানো ভিডিও ({list.length})</p><div className="grid grid-cols-3 gap-[2px] mt-2 pb-24">{list.map((v: any) => (<div key={v.id} onClick={() => onOpenVideo(v)} className="relative aspect-[9/16] bg-zinc-900 overflow-hidden cursor-pointer"><video src={v.url} muted playsInline preload="metadata" className="h-full w-full object-cover" /><div className="absolute bottom-1 left-1 text-[11px]">❤️ {v.likes}</div></div>))}</div></div>); }
function CreateWithSound({ sound, onClose }: any) { const [caption, setCaption] = useState(""); const [file, setFile] = useState<any>(null); const up = async () => { if (!file) return toast.error("একটা ভিডিও বেছে নাও"); toast("আপলোড হচ্ছে..."); try { const { data: { user } } = await sb.auth.getUser(); if (!user) return toast.error("আগে লগইন করো"); const path = `${user.id}/${Date.now()}-${file.name}`; const { error } = await sb.storage.from("videos").upload(path, file); if (error) throw error; await sb.from("videos").insert({ user_id: user.id, video_url: path, caption: caption || "এই গান দিয়ে বানালাম 🎵", sound_name: sound, visibility: "public" }); pushNotify("✅ ভিডিও পোস্ট হয়ে গেছে", "তোমার ভিডিও এখন সবাই দেখতে পারবে"); toast.success("হয়ে গেছে ✅"); onClose(); window.location.reload(); } catch { toast.error("আপলোড হয়নি"); } }; return (<div className="fixed inset-0 z-[120] bg-black/80 flex items-end justify-center" onClick={onClose}><div className="w-full max-w-[420px] bg-white rounded-t-3xl p-4 text-black" onClick={(e) => e.stopPropagation()}><div className="flex justify-between"><b>🎵 এই গান দিয়ে ভিডিও বানাও</b><button onClick={onClose} className="text-2xl px-2">×</button></div><p className="text-[12px] text-zinc-500 mt-1 bg-zinc-100 rounded-full px-3 py-2">🎵 {sound}</p><label className="block mt-3 bg-zinc-100 rounded-2xl p-6 text-center cursor-pointer"><p className="text-3xl">📹</p><p className="font-bold text-sm mt-1">{file ? file.name : "গ্যালারি থেকে ভিডিও বেছে নাও"}</p><input type="file" accept="video/*" className="hidden" onChange={(e) => setFile(e.target.files?.[0] || null)} /></label><input value={caption} onChange={(e) => setCaption(e.target.value)} placeholder="ক্যাপশন লিখো..." className="w-full mt-3 bg-zinc-100 rounded-2xl px-4 py-3 text-sm outline-none" /><button onClick={up} className="w-full mt-3 bg-[#fe2c55] text-white rounded-full py-3 font-bold">🎵 এই গান দিয়ে পোস্ট করো →</button></div></div>); }
function EditProfile({ info, sotId, currentUser, onClose, onSaved }: any) { const [name, setName] = useState(info?.full_name || currentUser?.name || ""); const [username, setUsername] = useState(info?.username || sotId || ""); const [bio, setBio] = useState(info?.bio || ""); const [website, setWebsite] = useState(info?.website || ""); const [gender, setGender] = useState(info?.gender || "Male"); const [avatar, setAvatar] = useState(info?.avatar_url || currentUser?.avatar || ""); const save = async () => { const nv = { full_name: name, username, bio, website, gender, avatar_url: avatar }; try { if (info?.id) await sb.from("profiles").update({ username, bio, website, gender, avatar_url: avatar } as any).eq("id", info.id); } catch {} if (currentUser) { setLocal("shorttok_persist_login", { ...currentUser, name: name || username, avatar }); setLS("shorttok_username", name || username); } onSaved(nv); }; return (<div className="fixed inset-0 z-[150] bg-white text-black overflow-y-auto"><div className="flex items-center gap-3 px-3 py-3"><button onClick={onClose} className="text-2xl">←</button><b className="text-[18px]">Edit profile</b><button onClick={save} className="ml-auto text-blue-600 font-bold">Done</button></div><div className="flex flex-col items-center mt-2">{avatar ? <img src={avatar} className="h-24 w-24 rounded-full object-cover" alt="" /> : <div className="h-24 w-24 rounded-full bg-gradient-to-br from-orange-500 to-pink-600 flex items-center justify-center text-3xl font-bold text-white">{(name || username || "S")[0].toUpperCase()}</div>}<label className="text-blue-600 font-medium mt-2 cursor-pointer">Edit picture or avatar<input type="file" accept="image/*" className="hidden" onChange={(e) => { const f = e.target.files?.[0]; if (f) setAvatar(URL.createObjectURL(f)); }} /></label></div><div className="px-4 mt-4 space-y-3 pb-10"><div className="border rounded-xl px-3 py-2"><p className="text-[12px] text-zinc-500">Name</p><input value={name} onChange={(e) => setName(e.target.value)} className="w-full outline-none font-medium" placeholder="Somnath Roy" /></div><div className="border rounded-xl px-3 py-2"><p className="text-[12px] text-zinc-500">Username</p><input value={username} onChange={(e) => setUsername(e.target.value)} className="w-full outline-none font-medium" placeholder="somnath__701" /></div><div className="border rounded-xl px-3 py-2"><p className="text-[12px] text-zinc-500">Bio</p><textarea value={bio} onChange={(e) => setBio(e.target.value)} className="w-full outline-none" rows={2} placeholder="My life 😊 my rules 😊 my style" /></div><div className="border rounded-xl px-3 py-2"><p className="text-[12px] text-zinc-500">Link / Website</p><input value={website} onChange={(e) => setWebsite(e.target.value)} className="w-full outline-none" placeholder="your-link.com" /></div><div className="border rounded-xl px-3 py-2 flex items-center justify-between"><div><p className="text-[12px] text-zinc-500">Gender</p><p className="font-medium">{gender}</p></div><select value={gender} onChange={(e) => setGender(e.target.value)} className="outline-none bg-transparent"><option>Male</option><option>Female</option><option>Other</option></select></div><p className="text-[12px] text-zinc-400">Short Tok ID: {sotId} — এটা বদলানো যাবে না</p><button onClick={save} className="w-full bg-[#fe2c55] text-white rounded-full py-3 font-bold">Save করে দাও ✅</button></div></div>); }
function ProfileView({ sotId, onClose, allVideos, onOpenVideo, currentUser, onLogout, followed, onFollow, myUserId }: any) { const [info, setInfo] = useState<any>(null); const [myVideos, setMyVideos] = useState<any[]>([]); const [showEdit, setShowEdit] = useState(false); const [tab, setTab] = useState("posts"); const [highlights, setHighlights] = useState<any[]>(() => getLocal(`shorttok_highlights_${sotId}`, [])); useEffect(() => { (async () => { try { const { data } = await sb.from("profiles").select("*").eq("sottok_id", sotId).single(); if (data) setInfo(data); } catch {} const mine = allVideos.filter((v: any) => v.sotId === sotId || v.username.replace("@", "") === sotId); setMyVideos(mine.length ? mine : allVideos.slice(0, 3)); })(); }, [sotId, allVideos]); const isMe = currentUser && (currentUser.name === (info?.username || sotId) || currentUser.email?.split("@")[0] === sotId || myUserId === info?.id); const avatar = info?.avatar_url || ""; const displayName = info?.username || sotId; const bio = info?.bio || "Short Tok Creator"; const totalLikes = myVideos.reduce((s: number, v: any) => s + (v.likes || 0), 0); const share = async () => { const url = `${window.location.origin}/feed`; try { if (navigator.share) await navigator.share({ title: `Short Tok - @${displayName}`, text: bio, url }); else { await navigator.clipboard.writeText(url); toast.success("প্রোফাইল লিঙ্ক কপি হয়েছে"); } } catch {} }; return (<div className="fixed inset-0 z-[90] bg-white text-black overflow-y-auto pb-24"><div className="sticky top-0 bg-white z-10 flex items-center justify-center px-3 py-3 border-b relative"><button onClick={onClose} className="absolute right-3 bg-zinc-100 p-2 rounded-full"><X className="h-4 w-4" /></button><p className="font-bold text-[16px]">{displayName} <span className="text-zinc-400">▼</span></p></div><div className="flex items-center gap-4 px-4 pt-4"><div className="relative shrink-0">{avatar ? <img src={avatar} className="h-20 w-20 rounded-full object-cover border-2 border-zinc-200" alt="" /> : <div className="h-20 w-20 rounded-full bg-gradient-to-br from-orange-500 to-pink-600 flex items-center justify-center text-3xl font-bold text-white">{(displayName || "S")[0].toUpperCase()}</div>}{isMe && <button onClick={() => setShowEdit(true)} className="absolute -bottom-1 -right-1 bg-[#fe2c55] text-white h-6 w-6 rounded-full flex items-center justify-center text-lg font-bold border-2 border-white">+</button>}</div><div className="flex-1 flex justify-around text-center"><div><p className="font-bold text-[16px]">{myVideos.length}</p><p className="text-[12px] text-zinc-500">posts</p></div><div><p className="font-bold text-[16px]">{(info?.followers_count || 0) + (followed ? 1 : 0)}</p><p className="text-[12px] text-zinc-500">followers</p></div><div><p className="font-bold text-[16px]">{info?.following_count || 0}</p><p className="text-[12px] text-zinc-500">following</p></div></div></div><div className="px-4 mt-2"><p className="font-bold text-[14px]">{info?.full_name || displayName} {isMe ? "✓" : ""}</p><p className="text-[13px] whitespace-pre-line">{bio}</p>{info?.website && <p className="text-[13px] text-blue-600 font-medium mt-0.5">🔗 {info.website}</p>}<p className="text-[12px] text-zinc-500 mt-0.5">Short Tok ID: {sotId} • ❤️ {totalLikes} লাইক</p></div><div className="flex gap-2 px-4 mt-3">{isMe ? (<><button onClick={() => setShowEdit(true)} className="flex-1 bg-zinc-100 rounded-lg py-2 text-[13px] font-bold">Edit profile</button><button onClick={share} className="flex-1 bg-zinc-100 rounded-lg py-2 text-[13px] font-bold">Share profile</button><button onClick={onLogout} className="bg-zinc-100 rounded-lg px-3 py-2 text-[13px] font-bold">Log Out</button></>) : (<><button onClick={onFollow} className={`flex-1 rounded-lg py-2 text-[13px] font-bold ${followed ? "bg-zinc-100 text-black" : "bg-[#fe2c55] text-white"}`}>{followed ? "✓ Following" : "+ Follow"}</button><button onClick={share} className="flex-1 bg-zinc-100 rounded-lg py-2 text-[13px] font-bold">Share profile</button><button onClick={() => toast.success("মেসেজ অপশন শীঘ্রই আসছে")} className="flex-1 bg-zinc-100 rounded-lg py-2 text-[13px] font-bold">Message</button></>)}</div>{isMe && <div className="mx-4 mt-3 bg-zinc-100 rounded-xl p-3"><p className="font-bold text-[13px]">Professional dashboard</p><p className="text-[12px] text-zinc-500">New tools are now available.</p></div>}<div className="flex gap-3 overflow-x-auto px-4 mt-3 pb-1"><button onClick={() => { if (isMe) { const t = prompt("Highlights এর নাম দাও"); if (t) { const nh = [...highlights, { id: Date.now(), name: t }]; setHighlights(nh); setLocal(`shorttok_highlights_${sotId}`, nh); } } }} className="flex flex-col items-center shrink-0"><div className="h-16 w-16 rounded-full border-2 border-zinc-200 flex items-center justify-center text-3xl">+</div><span className="text-[11px] mt-1">New</span></button>{highlights.map((h: any) => (<div key={h.id} className="flex flex-col items-center shrink-0"><div className="h-16 w-16 rounded-full border-2 border-[#fe2c55] bg-zinc-100 flex items-center justify-center font-bold">⭐</div><span className="text-[11px] mt-1 max-w-[64px] truncate">{h.name}</span></div>))}</div><div className="flex border-t mt-3"><button onClick={() => setTab("posts")} className={`flex-1 py-2 text-center text-lg ${tab === "posts" ? "border-b-2 border-black" : "text-zinc-400"}`}>▦</button><button onClick={() => setTab("saved")} className={`flex-1 py-2 text-center text-lg ${tab === "saved" ? "border-b-2 border-black" : "text-zinc-400"}`}>▶</button></div><div className="grid grid-cols-3 gap-[2px] mt-1 pb-6">{(tab === "posts" ? myVideos : myVideos.slice(0, 1)).map((v: any) => (<div key={v.id} onClick={() => onOpenVideo(v)} className="relative aspect-[3/4] bg-zinc-100 overflow-hidden cursor-pointer"><video src={v.url} muted playsInline preload="metadata" className="h-full w-full object-cover" /><div className="absolute bottom-1 left-1 text-[11px] text-white drop-shadow">❤️ {v.likes}</div><button onClick={(e) => { e.stopPropagation(); void downloadWithWatermark(v); }} className="absolute bottom-1 right-1 bg-black/70 p-1.5 rounded-full text-white"><Download className="h-3.5 w-3.5" /></button></div>))}</div>{showEdit && <EditProfile info={info} sotId={sotId} currentUser={currentUser} onClose={() => setShowEdit(false)} onSaved={(nv: any) => { setInfo((p: any) => ({ ...p, ...nv })); setShowEdit(false); toast.success("প্রোফাইল আপডেট হয়ে গেছে ✅"); }} />}</div>); }
function Explorer({ allVideos, creators, onClose, onOpenVideo, onOpenProfile, onJoin }: any) { const [tab, setTab] = useState("trending"); const trending = [...allVideos].sort((a: any, b: any) => (b.views + b.likes * 10) - (a.views + a.likes * 10)).slice(0, 12); const ranked = [...creators].sort((a: any, b: any) => b.totalLikes - a.totalLikes).map((c: any, i: number) => ({ ...c, rank: i + 1, points: c.totalLikes + c.count * 100 })); const challenges = [{ id: "c1", title: "🔥 নাচের চ্যালেঞ্জ", month: "নভেম্বর 2026", desc: "এই গানে নাচের ভিডিও বানাও", img: "https://images.unsplash.com/photo-1508700115892-45ecd05ae2ad?w=600", joined: 1240, prize: "🏆 ১ম পুরস্কার - 5000 পয়েন্ট", sound: "Original sound - Short Tok Artist", tag: "#DanceChallenge" }, { id: "c2", title: "🍛 রান্নার চ্যালেঞ্জ", month: "নভেম্বর 2026", desc: "৫ মিনিটে সেরা রান্না দেখাও", img: "https://images.unsplash.com/photo-1556910103-1c02745aae4d?w=600", joined: 980, prize: "🏆 ১ম পুরস্কার - 4000 পয়েন্ট", sound: "Original sound - Short Tok Artist", tag: "#CookingChallenge" }, { id: "c3", title: "😂 কমেডি চ্যালেঞ্জ", month: "ডিসেম্বর 2026", desc: "সবচেয়ে মজার ভিডিও বানাও", img: "https://images.unsplash.com/photo-1527224538127-2104bb71c51b?w=600", joined: 2100, prize: "🏆 ১ম পুরস্কার - 6000 পয়েন্ট", sound: "Original sound - Short Tok Artist", tag: "#ComedyChallenge" }, { id: "c4", title: "👨‍👩‍👧 ফ্যামিলি চ্যালেঞ্জ", month: "ডিসেম্বর 2026", desc: "পরিবারের সাথে মজার ভিডিও", img: "https://images.unsplash.com/photo-1511895426328-dc8714191300?w=600", joined: 750, prize: "🏆 ১ম পুরস্কার - 3000 পয়েন্ট", sound: "Original sound - Short Tok Artist", tag: "#FamilyChallenge" }]; return (<div className="fixed inset-0 z-[110] bg-white text-black overflow-y-auto pb-24"><div className="sticky top-0 bg-white z-10 flex items-center gap-2 px-3 py-3 border-b"><button onClick={onClose} className="bg-zinc-100 p-2 rounded-full"><X className="h-4 w-4" /></button><b className="text-[17px]">🧭 এক্সপ্লোরার</b><span className="ml-auto bg-[#fe2c55] text-white text-[11px] font-bold px-2 py-1 rounded-full">LIVE 🔴</span></div><div className="flex gap-2 px-3 mt-3"><button onClick={() => setTab("trending")} className={`flex-1 py-2 rounded-full text-[13px] font-bold ${tab === "trending" ? "bg-black text-white" : "bg-zinc-100"}`}>🔥 ট্রেন্ডিং</button><button onClick={() => setTab("challenge")} className={`flex-1 py-2 rounded-full text-[13px] font-bold ${tab === "challenge" ? "bg-black text-white" : "bg-zinc-100"}`}>🏆 চ্যালেঞ্জ</button><button onClick={() => setTab("rank")} className={`flex-1 py-2 rounded-full text-[13px] font-bold ${tab === "rank" ? "bg-black text-white" : "bg-zinc-100"}`}>🥇 র‍্যাংকিং</button></div>{tab === "trending" && (<div className="px-3 mt-3"><p className="font-bold text-[14px]">🔥 এখন ট্রেন্ডিং-এ যারা যাচ্ছে</p><div className="grid grid-cols-3 gap-[2px] mt-2">{trending.map((v: any, i: number) => (<div key={v.id} onClick={() => onOpenVideo(v)} className="relative aspect-[9/16] bg-zinc-100 overflow-hidden cursor-pointer"><video src={v.url} muted playsInline preload="metadata" className="h-full w-full object-cover" /><span className="absolute top-1 left-1 bg-[#fe2c55] text-white text-[11px] font-bold px-1.5 rounded-full">#{i + 1} 🔥</span><div className="absolute bottom-1 left-1 text-[11px] text-white drop-shadow">👁 {formatCompact(v.views)} • ❤️ {formatCompact(v.likes)}</div></div>))}</div></div>)}{tab === "challenge" && (<div className="px-3 mt-3 space-y-3"><p className="font-bold text-[14px]">🏆 চ্যালেঞ্জ — ছবি দেখে জয়েন করো</p>{challenges.map((c: any) => (<div key={c.id} className="rounded-2xl overflow-hidden border border-zinc-200"><div className="relative"><img src={c.img} className="w-full h-[160px] object-cover" alt="" /><span className="absolute top-2 left-2 bg-black/70 text-white text-[11px] font-bold px-2 py-1 rounded-full">{c.month} • চলছে</span><span className="absolute top-2 right-2 bg-[#fe2c55] text-white text-[11px] font-bold px-2 py-1 rounded-full">{c.joined} জন জয়েন করেছে</span></div><div className="p-3"><p className="font-bold text-[15px]">{c.title}</p><p className="text-[12px] text-zinc-500">{c.desc} • {c.tag}</p><p className="text-[12px] font-bold text-orange-600 mt-1">{c.prize}</p><button onClick={() => onJoin(c.sound)} className="w-full mt-2 bg-[#fe2c55] text-white rounded-full py-2.5 font-bold text-[13px]">🎬 এই চ্যালেঞ্জে জয়েন করো →</button></div></div>))}</div>)}{tab === "rank" && (<div className="px-3 mt-3"><p className="font-bold text-[14px]">🥇 র‍্যাংকিং — কে কত নাম্বারে আছে</p><div className="space-y-2 mt-2">{ranked.map((c: any) => (<button key={c.sotId || c.username} onClick={() => onOpenProfile(c.sotId || c.username.replace("@", ""))} className="w-full flex items-center gap-3 bg-zinc-100 rounded-2xl p-3 text-left"><span className={`w-8 h-8 shrink-0 rounded-full flex items-center justify-center font-bold text-white ${c.rank === 1 ? "bg-yellow-500" : c.rank === 2 ? "bg-zinc-400" : c.rank === 3 ? "bg-orange-700" : "bg-zinc-300 text-black"}`}>{c.rank === 1 ? "🥇" : c.rank === 2 ? "🥈" : c.rank === 3 ? "🥉" : c.rank}</span><div className="h-11 w-11 rounded-full bg-gradient-to-br from-orange-500 to-pink-600 flex items-center justify-center font-bold text-white">{c.username.replace("@", "")[0].toUpperCase()}</div><div className="flex-1 min-w-0"><p className="font-bold text-[14px] truncate">{c.username} {c.rank <= 3 ? "👑" : ""}</p><p className="text-[12px] text-zinc-500">{c.count} টা ভিডিও • {c.totalLikes} লাইক • {c.points} পয়েন্ট</p></div><span className="text-[12px] font-bold text-[#fe2c55]">প্রোফাইল →</span></button>))}</div></div>)}</div>); }
