function useFeed() { return useInfiniteQuery({ queryKey: ["feed"], initialPageParam: 0, staleTime: 60000, gcTime: 300000, refetchOnWindowFocus: false, getNextPageParam: (last: any, pages: any) => (last.length < 6 ? undefined : pages.length), queryFn: async ({ pageParam }: any) => { const from = (pageParam as number) * 6; try { const { data } = await sb.from("videos").select("id, caption, video_url, sound_name, views, likes, comments_count, user_id").eq("visibility", "public").eq("is_deleted", false).order("created_at", { ascending: false }).range(from, from + 5); const rows = data ?? []; if (!rows.length) return []; const ids = [...new Set(rows.map((v: any) => v.user_id))]; const [{ data: profiles }, urls] = await Promise.all([sb.from("profiles").select("id, username, sottok_id, avatar_url").in("id", ids), signBatch(rows.map((v: any) => v.video_url))]); const nBy = new Map((profiles ?? []).map((p: any) => [p.id, p.username])); const sBy = new Map((profiles ?? []).map((p: any) => [p.id, p.sottok_id])); const aBy = new Map((profiles ?? []).map((p: any) => [p.id, p.avatar_url])); return rows.map((v: any) => ({ id: v.id, userId: v.user_id, sotId: sBy.get(v.user_id), avatar: aBy.get(v.user_id), username: "@" + (nBy.get(v.user_id) || "shorttok"), caption: v.caption, url: urls.get(v.video_url) ?? "", sound: v.sound_name, views: v.views ?? 0, likes: v.likes ?? 0, comments: (v.comments_count ?? 0) + getLocal(`shorttok_comments_${v.id}`, []).length })).filter((r: any) => r.url); } catch { return []; } } }); }
