function BottomNav({ statusCount, onOpenStatus, currentUser, onLogin, onOpenExplorer }: any) { return (<div className="fixed bottom-0 left-1/2 -translate-x-1/2 w-full max-w-[420px] z-50 bg-[#111] border-t border-zinc-800 flex justify-around items-center py-2 px-1 text-white"><Link to="/feed" className="flex flex-col items-center gap-0.5 w-[60px]"><Home className="h-6 w-6 text-[#fe2c55]" /><span className="text-[11px] font-bold text-[#fe2c55]">হোম</span></Link><button onClick={onOpenExplorer} className="flex flex-col items-center gap-0.5 w-[60px]"><Compass className="h-6 w-6 text-white/80" /><span className="text-[11px] text-white/70">এক্সপ্লোরার</span></button><button onClick={onOpenStatus} className="flex flex-col items-center gap-0.5 w-[60px] relative"><span className="relative"><CircleDot className="h-6 w-6 text-green-400" />{statusCount ? <span className="absolute -top-1 -right-2 bg-[#fe2c55] text-[9px] font-bold px-1 rounded-full">{statusCount}</span> : null}</span><span className="text-[11px] font-bold text-green-400">স্ট্যাটাস</span></button><Link to="/upload" className="flex flex-col items-center w-[60px]"><span className="h-10 w-10 rounded-full bg-[#fe2c55] flex items-center justify-center"><Plus className="h-6 w-6 text-white" /></span></Link><Link to="/inbox" className="flex flex-col items-center gap-0.5 w-[60px]"><Bell className="h-6 w-6 text-white/80" /><span className="text-[11px] text-white/70">ইনবক্স</span></Link><button onClick={onLogin} className="flex flex-col items-center gap-0.5 w-[60px]"><span className="h-6 w-6 rounded-full bg-gradient-to-br from-orange-500 to-pink-600 flex items-center justify-center text-[12px] font-bold">{currentUser ? (currentUser.name?.[0] || "U").toUpperCase() : <User className="h-5 w-5" />}</span><span className="text-[11px] text-white/70 max-w-[60px] truncate">{currentUser ? currentUser.name : "প্রোফাইল"}</span></button></div>); }
