  const [likedIds, setLikedIds] = useState<Set<string>>(() => new Set(getLocal("shorttok_liked", []))); const [likeDelta, setLikeDelta] = useState<Record<string, number>>({}); const [commentDelta, setCommentDelta] = useState<Record<string, number>>({});
  const [openGift, setOpenGift] = useState<string | null>(null); const [giftAnim, setGiftAnim] = useState<any>(null);
  const [openComments, setOpenComments] = useState<any>(null); const [openProfileId, setOpenProfileId] = useState<string | null>(null);
  const [fullVideo, setFullVideo] = useState<any>(null); const [followSet, setFollowSet] = useState<Set<string>>(() => new Set(getLocal("shorttok_follow", [])));
  const [openSound, setOpenSound] = useState<string | null>(null); const [showCreateWithSound, setShowCreateWithSound] = useState<string | null>(null);
  const [statuses, setStatuses] = useState<any[]>(() => getLocal("shorttok_status_list", [])); const [showAddStatus, setShowAddStatus] = useState(false); const [viewStatusIdx, setViewStatusIdx] = useState<number | null>(null);
  const [showStatusPage, setShowStatusPage] = useState(false); const [showPrivacy, setShowPrivacy] = useState(false); const [showExplorer, setShowExplorer] = useState(false);
