  const sounds = useMemo(() => { const map = new Map<string, number>(); items.forEach((v) => { if (v.sound) map.set(v.sound, (map.get(v.sound) || 0) + 1); }); return [...map.entries()].sort((a, b) => b[1] - a[1]).slice(0, 5); }, [items]);
