  async function toggleFollow(other?: string) { if (!other) return; if (!currentUser && !user) return setShowLogin(true); const was = followSet.has(other); const next = new Set(followSet); if (was) next.delete(other); else next.add(other); setFollowSet(next); setLocal("shorttok_follow", [...next]); if (user) { try { await setFollow(user.id, other, !was); } catch {} } toast.success(was ? "আনফলো করা হয়েছে" : "ফলো করা হয়েছে"); pushNotify(was ? "আনফলো" : "✅ নতুন ফলো", was ? "আনফলো করা হয়েছে" : "তুমি একজনকে ফলো করেছো"); }
